/* ==UserStyle==
@name Lingva Catppuccin
@namespace github.com/catppuccin/userstyles/styles/lingva
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/lingva
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/lingva/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Alingva
@description Soothing pastel theme for Lingva
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("lingva.ml"),
  domain("translate.plausibility.cloud"),
  domain("lingva.lunar.icu"),
  domain("translate.projectsegfau.lt"),
  domain("lingva.garudalinux.org") {
  .chakra-ui-light {
    #catppuccin(@lightFlavor);
  }
  .chakra-ui-dark {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    body {
      background: @base;
      color: @text;
    }

    header {
      background-color: @accent;

      .chakra-button {
        color: darken(@accent, 50%);
        background: lighten(@accent, 5%);
        &:hover {
          background: darken(@accent, 5%);
        }
      }
    }

    footer {
      background-color: @accent;
      color: darken(@accent, 50%);
    }

    #__next > div {
      background: @base;
    }

    main {
      background: @base;
      color: @text;

      select {
        border-color: @accent;
        color: @text;
      }
      .chakra-select__icon {
        color: @text;
      }
      .chakra-button {
        color: @accent;
        border-color: @accent;

        &:hover:not(:disabled) {
          background-color: fade(@accent, 12%);
        }

        // Auto translate button (clicked) (Dark and Light classes)
        &.css-1huvcr7,
        &.css-q22xb2 {
          background: @accent;
          color: @crust;
        }
      }
      .chakra-stack {
        border-color: @accent;
      }

      textarea {
        color: @text;
      }

      .chakra-text {
        color: @subtext1;
      }
    }
  }
}

